/**
 * Chain-scoped test data for protocol-coverage fixtures (KEEP-458).
 *
 * Authoritative for: known testnet tokens, faucet contracts, fork-mode whale
 * addresses. The persistent E2E test user's wallet address is NOT here --
 * KEEP-529 made it HSM-generated by Turnkey, so the address differs per
 * environment. Callers look it up from `organization_wallets` at test/seed
 * time and pass it into the builders in `lib/test-data/build-workflow.ts`.
 *
 * Where addresses come from:
 *   - Tokens are extracted/extended from `scripts/seed/seed-tokens.ts` and from
 *     existing usage in `tests/integration/protocol-superfluid-onchain.test.ts`.
 *   - Aave V3 Sepolia faucet is from Aave's address book (verify against
 *     https://aave.com/docs/resources/addresses before relying on it).
 *   - Mainnet whale addresses are large protocol-held balances verified via
 *     Etherscan token-holder rankings at the time of writing.
 */

/** Env var name the funder script reads. The PK itself must never appear in code. */
export const TESTNET_FUNDER_PK_ENV = "TESTNET_FUNDER_PK";

/**
 * Chain IDs where anvil fork-mode provisioning applies. On these chains
 * ensureNativeGas uses anvil_setBalance and ensureErc20Acquired uses whale
 * impersonation or an impersonated faucet mint instead of a real funder
 * EOA + testnet faucets.
 *
 * Sepolia (11155111) moved to fork mode after live-testnet runs proved
 * economically unviable on ephemeral CI: each run seeds a fresh Turnkey
 * wallet (stranding every top-up), and 2026-07-02 base-fee spikes of
 * 40-105 gwei priced a single worst-case Superfluid tx above any top-up
 * the shared funder could sustain. Since the chronicle/superfluid
 * re-homing to the mainnet fork, no Tier 2 suite targets Sepolia and CI
 * runs no Sepolia fork; the entry stays for the remaining Sepolia
 * testData (aave-v3) exercised by local Tier 1 sims
 * (scripts/protocol-local.sh sim sepolia).
 */
export const FORK_CHAIN_IDS: Set<string> = new Set([
  "1",
  "11155111",
  "8453",
  "42161",
]);

