/** Faucet contract that mints a testnet token to a recipient. */
export type FaucetSpec = {
  contract: string;
  functionName: string;
  /** Full ABI JSON for the mint function, single-element array. */
  abi: string;
};

/**
 * Faucet registry consumed by `tests/e2e/vitest/protocol-coverage/_shared/funding.ts`.
 * The TS preflight calls each faucet from the funder EOA before the setup
 * workflow runs. Args are bound by input *name* (case-insensitive):
 *   `token` -> token's address on this chain
 *   `to` / `recipient` -> the test wallet address
 *   `amount` / `value` -> requiredTokens[i].human in wei (using token decimals)
 *
 * Fork-mode chains (FORK_CHAIN_IDS) use whale impersonation instead of faucets.
 * Their entries here are intentionally absent; ensureErc20Acquired delegates to
 * ensureErc20OnFork before reaching the FAUCETS lookup.
 */
export const FAUCETS: Record<
  string /* chainId */,
  Partial<Record<TokenSymbol, FaucetSpec>>
> = {
  "11155111": {
    // Aave V3 Sepolia faucet: mints any Aave testnet reserve token.
    // Verified contract exists at this address (eth_getCode).
    LINK: {
      contract: "0xC959483DBa39aa9E78757139af0e9a2EDEb3f42D",
      functionName: "mint",
      abi: JSON.stringify([
        {
          type: "function",
          name: "mint",
          stateMutability: "nonpayable",
          inputs: [
            { name: "token", type: "address" },
            { name: "to", type: "address" },
            { name: "amount", type: "uint256" },
          ],
          outputs: [{ name: "", type: "uint256" }],
        },
      ]),
    },
  },
};

